using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class NightLanternBiasChecks {
 [Serializable] class Report {public bool pass;public string error,scope="isolated comparison; each isolated object differs only in its material keyword; stone trials are not adopted";public List<string> rendered=new List<string>();public List<long> meshMemoryBytes=new List<long>();}
 static string Arg(string k){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,k)+1];}
 public static void Run(){string output=Arg("-props-output"),source=Arg("-props-export");Directory.CreateDirectory(output);var report=new Report();int code=0;try{
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var data=SmallPropsV1.Read(Path.Combine(source,"small_props.json"));var built=MapSharedPropsBuilder.Build(source);built.root.SetActive(false);
  var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));
  var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*3;var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.SetColor("_BaseColor",new Color(.22f,.17f,.11f));floor.GetComponent<Renderer>().sharedMaterial=fm;
  var camera=new GameObject("Small props proof camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.fieldOfView=50;camera.aspect=1.28f;camera.backgroundColor=Color.black;camera.clearFlags=CameraClearFlags.SolidColor;var rt=new RenderTexture(1280,1000,24,RenderTextureFormat.ARGB32);camera.targetTexture=rt;

 foreach(string id in (Array.IndexOf(Environment.GetCommandLineArgs(),"-props-ids")>=0?Arg("-props-ids").Split(','):new[]{"lantern","crossgrave","gravestone"})){var a=Array.Find(data.assets,x=>x.id==id);foreach(string mode in new[]{"source","standard-bias"})foreach(int angle in new[]{0,1})foreach(string frame in new[]{"head","full"}){sun.transform.rotation=Quaternion.LookRotation(angle==0?new Vector3(-5,-9,-4):new Vector3(4,-8,5));
 var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id]);o.transform.position=Vector3.down*a.groundSink;var renderer=o.GetComponent<Renderer>();Mesh clone=null;Material diagnosticMaterial=null;
 if(mode=="flat-normal-diagnostic"){clone=UnityEngine.Object.Instantiate(o.GetComponent<MeshFilter>().sharedMesh);clone.RecalculateNormals();o.GetComponent<MeshFilter>().sharedMesh=clone;}
 if(mode=="local-cast-off-diagnostic")renderer.shadowCastingMode=ShadowCastingMode.Off;
 if(mode=="emission-off-diagnostic"){diagnosticMaterial=UnityEngine.Object.Instantiate(renderer.sharedMaterial);diagnosticMaterial.DisableKeyword("SHARED_GLOW");renderer.sharedMaterial=diagnosticMaterial;}
diagnosticMaterial=UnityEngine.Object.Instantiate(renderer.sharedMaterial);if(mode=="source")diagnosticMaterial.DisableKeyword("SMALL_PROP_SHADOW_BIAS");else diagnosticMaterial.EnableKeyword("SMALL_PROP_SHADOW_BIAS");renderer.sharedMaterial=diagnosticMaterial;if(ShaderUtil.ShaderHasError(diagnosticMaterial.shader))throw new Exception("Product shader compile error");
 float target=frame=="head"?(id=="lantern"?1.58f:a.height*.5f):a.height*.42f,d=frame=="head"?(id=="lantern"?1.4f:1.6f):Mathf.Max(2.2f,a.height*1.9f,o.GetComponent<MeshFilter>().sharedMesh.bounds.size.x*1.7f);camera.transform.position=new Vector3(d*.6f,target+d*.35f,-d*.8f);camera.transform.rotation=Quaternion.LookRotation(new Vector3(frame=="head"&&id=="lantern"?.42f:0,target,0)-camera.transform.position,Vector3.up);camera.Render();RenderTexture.active=rt;var png=new Texture2D(1280,1000,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1280,1000),0,0);png.Apply();File.WriteAllBytes(Path.Combine(output,id+"-"+mode+"-"+angle+"-"+frame+".png"),png.EncodeToPNG());report.rendered.Add(id+"/"+mode+"/"+angle+"/"+frame);report.meshMemoryBytes.Add(UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(o.GetComponent<MeshFilter>().sharedMesh));UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(o);if(clone)UnityEngine.Object.DestroyImmediate(clone);if(diagnosticMaterial)UnityEngine.Object.DestroyImmediate(diagnosticMaterial);
 }}report.pass=true;
 }catch(Exception e){report.error=e.ToString();Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}}
}
